#include <deque>
#include <iostream>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::deque<int> values;
    for (int i = 0; i < n; i++) {
        int value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -1000 || value > 1000) return 1;
        if (value % 2 == 0) {
            values.push_back(value);
        } else {
            values.push_front(value);
        }
    }
    for (int value : values) {
        std::cout << value << "\n";
    }
    return 0;
}
